INTERPRET QUERY () FOR GRAPH OlympicGraph {
  SumAccum<INT> @@count = 0;
  Events = SELECT e FROM Games:g -(IN_GAMES_REVERSE:e)-> Event:e
           WHERE g.name LIKE "%2008 Summer%" 
             AND e.sport LIKE "%Cycling%"
             AND e.competitors > 30
           ACCUM @@count += 1;
  PRINT @@count;
}

INTERPRET QUERY () FOR GRAPH OlympicGraph {
  MaxAccum<INT> @@max_comp = 0;
  Events = SELECT e FROM Games:g -(IN_GAMES_REVERSE:e)-> Event:e
           WHERE g.name LIKE "%2016 Summer%" AND e.sport LIKE "%Sailing%"
           ACCUM @@max_comp += e.competitors
           ORDER BY e.competitors DESC
           LIMIT 1;
  PRINT Events;
}

